const body = $input.first().json.body || $input.first().json || {};
const repoUrl = typeof body.repoUrl === 'string' ? body.repoUrl.trim() : '';
const branch = (body.branch || 'main').trim();

const urlRegex = /^https?:\/\/github\.com\/([a-zA-Z0-9_.-]+)\/([a-zA-Z0-9_.-]+)(\/.*)?$/;
const match = repoUrl.match(urlRegex);
if (!match) {
  return [{ json: { hasError: true, error: { code: 'INVALID_URL', message: 'Please provide a valid public GitHub repository URL.' }, repoUrl } }];
}
const owner = match[1];
const repo = match[2].replace(/\.git$/, '').replace(/\/+$/, '');
return [{ json: { repoUrl, owner, repo, branch, hasError: false } }];

const meta = $("GitHub Repo Metadata").first().json || {};
const tree = $("GitHub File Tree").first().json || {};
const parsed = $("Parse Repo URL").first().json || {};

const ALLOWED = ['ts','tsx','js','jsx','py','go','java','rs','c','cpp','h','rb','php','sh','sql'];
const EXCLUDED_FIRST_DIRS = ['node_modules','dist','build','vendor','coverage','.venv','__pycache__'];
const EXCLUDED_MARKERS = ['/test/','/tests/','/spec/','/__tests__/','.min.js','.min.css','.lock','/fixtures/','/examples/'];

const files = (tree.tree || [])
  .filter(f => f.type === 'blob')
  .filter(f => {
    const path = f.path;
    const parts = path.split('/');
    if (parts.some(p => p.startsWith('.'))) return false;
    if (EXCLUDED_FIRST_DIRS.includes(parts[0])) return false;
    if (EXCLUDED_MARKERS.some(m => path.includes(m))) return false;
    if (f.size && f.size > 300000) return false;
    const ext = path.split('.').pop().toLowerCase();
    return ALLOWED.includes(ext);
  })
  .sort((a, b) => (b.size || 0) - (a.size || 0))
  .slice(0, 5);

const items = files.map(f => ({
  repoUrl: parsed.repoUrl || '',
  full_name: (parsed.owner && parsed.repo) ? `${parsed.owner}/${parsed.repo}` : '',
  owner: parsed.owner || '',
  repo: parsed.repo || '',
  branch: parsed.branch || meta.default_branch || 'main',
  filePath: f.path,
  size: f.size || 0
}));

return items.map(json => ({ json }));

const res = $input.first().json || {};

let content = '';
if (res && res.content && res.encoding === 'base64') {
  try { content = Buffer.from(res.content, 'base64').toString('utf-8'); } catch (e) { content = ''; }
}

const filePath = String(res.path || 'unknown').slice(0, 500);
const repoUrl = String(res.html_url || '').split('/blob/')[0];

if (!content || !content.trim()) {
  return [{ json: { repoUrl, full_name: repoUrl.replace('https://github.com/', ''), filePath, chunkIndex: 0, chunkText: '' } }];
}

const CHUNK_SIZE = 3500;
const OVERLAP = 200;
const MAX_LEN = 8000;
const body = content.slice(0, MAX_LEN);
const chunks = [];
for (let i = 0; i < body.length; i += CHUNK_SIZE - OVERLAP) {
  chunks.push(body.slice(i, i + CHUNK_SIZE));
}
if (chunks.length === 0) chunks.push(body);

return chunks.map((text, idx) => ({
  json: { repoUrl, full_name: repoUrl.replace('https://github.com/', ''), filePath, chunkIndex: idx, chunkText: text }
}));

function getVector(text) {
  const vec = new Array(768).fill(0);
  const words = String(text || '').toLowerCase().match(/[a-z0-9_$]+/g) || [];
  if (words.length === 0) return vec;

  for (const word of words) {
    let hash = 5381;
    for (let i = 0; i < word.length; i++) {
      hash = ((hash << 5) + hash) + word.charCodeAt(i);
      hash = hash & hash;
    }
    const idx = Math.abs(hash) % 768;
    vec[idx] += 1;
  }

  let norm = Math.sqrt(vec.reduce((sum, v) => sum + v * v, 0));
  if (norm === 0) norm = 1;
  return vec.map(v => Number((v / norm).toFixed(6)));
}

const items = $input.all();
return items.map(item => {
  const text = item.json.chunkText || '';
  const embedding = getVector(text);
  return {
    json: {
      data: [{ embedding }]
    }
  };
});

const chunks = $("Chunk File").all().map(i => i.json);
const embeds = $("Embed Chunk").all().map(i => i.json.data && i.json.data[0] && i.json.data[0].embedding);

const rows = [];
const seenFiles = new Set();
chunks.forEach((c, idx) => {
  const emb = embeds[idx];
  if (!Array.isArray(emb) || !c.chunkText || c.chunkText.length < 10) return;
  rows.push({ repo_url: c.repoUrl, full_name: c.full_name, file_path: c.filePath, chunk_index: c.chunkIndex, chunk_text: c.chunkText, embedding: emb });
  seenFiles.add(c.filePath);
});

return [{
  json: {
    rows,
    indexedFiles: seenFiles.size,
    repoUrl: rows[0]?.repoUrl || (chunks[0] && chunks[0].repoUrl) || '',
    full_name: rows[0]?.full_name || (chunks[0] && chunks[0].full_name) || '',
    hasError: rows.length === 0,
    error: rows.length === 0 ? { code: 'EMBED_FAILED', message: 'Could not embed any code chunks for this repository.' } : undefined
  }
}];

const zip = $("Zip Rows").first().json || {};
const repoUrl = zip.repoUrl || '';
return [{
  json: {
    type: 'done',
    repoUrl,
    full_name: zip.full_name || '',
    indexedFiles: zip.indexedFiles || 0,
    chunks: Array.isArray(zip.rows) ? zip.rows.length : 0,
    hasError: !zip.indexedFiles,
    error: zip.error || null
  }
}];
